-- Expense bounded context core tables (P5.1): expense, expense_settings,
-- audit_log. Cross-service references (employee, manager) are UUIDs only —
-- no foreign keys outside this schema (§2.4).
-- Must run on PostgreSQL (compose) AND H2 in PostgreSQL mode (local/tests):
-- stick to the common SQL subset — UUIDs are generated by the application.

create table expense (
    id                        uuid primary key,
    -- hr employee id (cross-service reference, no FK)
    employee_id               uuid          not null,
    -- keycloak subject of the owner: BR-01 ownership checks vs jwt.sub
    employee_keycloak_id      uuid          not null,
    -- manager relationship SNAPSHOT taken at submit time (cached, §2.5);
    -- null when the claim is escalated to HR (BR-02 routing)
    manager_keycloak_id       uuid,
    hr_escalated              boolean       not null,
    category                  varchar(20)   not null,
    amount                    numeric(12,2) not null,
    currency                  varchar(3)    not null,
    expense_date              date          not null,
    description               varchar(500),
    status                    varchar(30)   not null,
    -- BR-03: set true at first approval once the claim exceeds the threshold
    second_approval_required  boolean       not null,
    first_approver_keycloak_id uuid,
    first_approved_at         timestamp with time zone,
    decided_by                uuid,
    decided_at                timestamp with time zone,
    decision_comment          varchar(500),
    created_at                timestamp with time zone not null,
    updated_at                timestamp with time zone not null,
    constraint ck_expense_category check (category in
        ('TRAVEL', 'MEALS', 'ACCOMMODATION', 'SUPPLIES', 'TRAINING', 'OTHER')),
    constraint ck_expense_status check (status in
        ('SUBMITTED', 'PENDING_SECOND_APPROVAL', 'APPROVED', 'REJECTED', 'CANCELLED')),
    constraint ck_expense_amount check (amount > 0)
);

create index ix_expense_employee       on expense (employee_keycloak_id);
create index ix_expense_manager_status on expense (manager_keycloak_id, status);
create index ix_expense_status         on expense (status);

-- Single-row settings table holding the configurable BR-03 threshold. Seeded
-- here so the service only ever updates it (never inserts).
create table expense_settings (
    setting_key varchar(40)   primary key,
    amount      numeric(12,2) not null,
    currency    varchar(3)    not null,
    updated_by  varchar(255),
    updated_at  timestamp with time zone not null,
    constraint ck_expense_settings_amount check (amount >= 0)
);

insert into expense_settings (setting_key, amount, currency, updated_by, updated_at)
values ('APPROVAL_THRESHOLD', 1000.00, 'EUR', 'system', now());

-- Append-only audit trail (BR-05): rows are only ever inserted. On PostgreSQL
-- the schema grants deny UPDATE/DELETE to the service role; H2 (dev/tests)
-- relies on the code path never issuing them.
create table audit_log (
    id          uuid         primary key,
    actor       varchar(255) not null,
    action      varchar(100) not null,
    resource    varchar(255) not null,
    details     varchar(2000),
    occurred_at timestamp with time zone not null
);

create index ix_audit_log_resource on audit_log (resource);
